import{_ as t,H as a,f as s,i}from"./chunks/framework.BH2BK_3i.js";const f=JSON.parse('{"title":"致「从0开始学架构」专栏订阅用户","description":"","frontmatter":{},"headers":[],"relativePath":"从0开始学架构/致「从0开始学架构」专栏订阅用户.md","filePath":"从0开始学架构/致「从0开始学架构」专栏订阅用户.md","lastUpdated":1779818431000}'),n={name:"从0开始学架构/致「从0开始学架构」专栏订阅用户.md"};function r(o,e,E,c,p,g){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="致「从0开始学架构」专栏订阅用户" tabindex="-1">致「从0开始学架构」专栏订阅用户 <a class="header-anchor" href="#致「从0开始学架构」专栏订阅用户" aria-label="Permalink to &quot;致「从0开始学架构」专栏订阅用户&quot;">​</a></h1><p>你好，我是华仔。在我的专栏结束后， <strong>今天又有一个好消息想分享给你，而且这件事情离不开每位订阅专栏同学的支持。</strong></p><p>事情的源起是「从0开始学架构」专栏发布时，我在InfoQ公众号文章的一条留言。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E5%AD%A6%E6%9E%B6%E6%9E%84/images/41397/740c2af41e4c203452e1cca3764c1b6b.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E5%AD%A6%E6%9E%B6%E6%9E%84/images/41397/740c2af41e4c203452e1cca3764c1b6b.jpg" alt=""></a></p><p>由于我一直有不定期捐助“免费午餐”的习惯，当时就想正好借此机会，完成一个小小的愿望：在专栏结束后，按照订阅人数，捐出同等数量的免费午餐。</p><p>9月，在专栏结束后，有26000人订阅了我的专栏，而我也兑现了当初的承诺，捐出了26000份免费午餐，耒阳市导子镇上古小学（ <a href="https://m.weibo.cn/u/6478785428?from=1089395010&amp;wm=9006_2001&amp;sourceType=weixin&amp;uid=2058877932" target="_blank" rel="noreferrer">微博</a>）的100个孩子可以放心吃上1年。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E5%AD%A6%E6%9E%B6%E6%9E%84/images/41397/99c5cf7ffbc1abb17a5393d4404f7aa8.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E5%AD%A6%E6%9E%B6%E6%9E%84/images/41397/99c5cf7ffbc1abb17a5393d4404f7aa8.jpeg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E5%AD%A6%E6%9E%B6%E6%9E%84/images/41397/912ad45ddf78ca313ce1f3299041a6e0.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BB%8E0%E5%BC%80%E5%A7%8B%E5%AD%A6%E6%9E%B6%E6%9E%84/images/41397/912ad45ddf78ca313ce1f3299041a6e0.jpg" alt=""></a></p><p>正如我当初立下的一个小小的flag：让技术既改变自己，也惠泽他人。通过专栏，我们一起学习进步，又一起完成100个孩子1年免费午餐的捐助，当初立下的flag算是完美达成。 <strong>我代表孩子们感谢订阅了专栏的你，也祝愿孩子们健康快乐成长，长大后成为优秀的架构师 ：）</strong></p>',9)])])}const h=t(n,[["render",r]]);export{f as __pageData,h as default};
